            }

            delegate "Remove duplicate or materially overlapping ideas from this list. Preserve distinct coverage and return the result in the required structured format.\n\nTest ideas:\n{generated_case_ideas.ideas}" to TestIdeaDeduplicator -> deduplicated_case_ideas expecting {
                ideas: list<string>
            } retry 0 backoff 2s timeout 60s on_failure {
                halt "Workflow could not complete: deduplication failed. No partial list is returned."
            }

            return { test_ideas: deduplicated_case_ideas.ideas }
